/*
 * A232868  Positions of the integers in the sequence (or tree) of complex
 *          numbers generated by these rules: 0 is in S, and if x is in S,
 *          then x + 1 and i*x are in S, where duplicates are deleted as they
 *          occur.
 * https://oeis.org/A232868
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = a(n-1) + 2*a(n-2) - 2*a(n-3) - a(n-4) + a(n-5) (n > 10)
 *            Initial values: a(1)=1, a(2)=2, a(3)=3, a(4)=5, a(5)=8, a(6)=9,
 *            a(7)=12, a(8)=16, a(9)=19, a(10)=27. The function is memoized
 *            implicitly via a sliding window; its complexity is O(n)
 * Range:     u8 n <= 25, u16 n <= 55, u32 n <= 55, u64 n <= 55, u128 n <= 55,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>

seq_t a(idx_t n)
{
    static const seq_t init[10] =
    { 1, 2, 3, 5, 8, 9, 12, 16, 19, 27 };

    if (n == 0) return 0;          /* undefined for n < 1, return 0 */
    if (n <= 10) return init[n - 1];

    /* values for a(n-5) .. a(n) for the current n */
    seq_t v0 = init[5];   /* a(6)  */
    seq_t v1 = init[6];   /* a(7)  */
    seq_t v2 = init[7];   /* a(8)  */
    seq_t v3 = init[8];   /* a(9)  */
    seq_t v4 = init[9];   /* a(10) */

    for (idx_t i = 11; i <= n; ++i) {
        seq_t next = v4 + 2 * v3 - 2 * v2 - v1 + v0;  /* a(i) */
        /* slide window */
        v0 = v1;
        v1 = v2;
        v2 = v3;
        v3 = v4;
        v4 = next;
    }
    return v4;   /* a(n) */
}
